node - <<'NODE'
const assert = require('node:assert/strict')
const semver = require('./src')
const includePrerelease = { includePrerelease: true }
for (const [version, range, expected] of [
  ['0.0.3-alpha', '^0.0.3', false],
  ['0.2.3-alpha', '^0.2.3', false],
  ['0.0.3', '^0.0.3', true],
  ['0.2.3', '^0.2.3', true],
  ['0.0.4-0', '^0.0.3', false],
  ['0.3.0-0', '^0.2.3', false],
  ['0.0.3-alpha', '^0.0.3-alpha', true],
  ['0.2.0-alpha', '^0.2', true],
  ['0.0.3-alpha', '^0.0', true],
]) {
  assert.equal(semver.satisfies(version, range, includePrerelease), expected, `${version} ${range}`)
}
console.log('targeted caret prerelease checks passed')
NODE

